record.field:
if records:
for task in records:
# Kiểm tra nếu công việc vừa được chuyển sang 'Hoàn thành'
if task.trang_thai == 'hoan_thanh':
project = task.du_an_id
if project:
# Lấy tất cả công việc của dự án này
all_tasks_in_project = env['cong_viec'].search([('du_an_id', '=', project.id)])
# Kiểm tra xem tất cả có trạng thái là 'hoan_thanh' không
if all(t.trang_thai == 'hoan_thanh' for t in all_tasks_in_project):
# Nếu đúng, cập nhật dự án
project.write({'trang_thai': 'hoan_thanh'})
